import React, { useState, useEffect, useRef } from 'react';
import './NewsWidget.css';

const NewsWidget = ({ onClose, isVisible = true, initialNews }) => {
  const [newsArticles, setNewsArticles] = useState([]);
  const [activeTab, setActiveTab] = useState('current'); // 'current' or 'history'
  const [isLoading, setIsLoading] = useState(false);
  const [newsHistory, setNewsHistory] = useState([]);
  const [newsCount, setNewsCount] = useState(0);
  const [italyTime, setItalyTime] = useState('--:--:--');

  // Custom Drag & Resize State
  const [widgetPos, setWidgetPos] = useState({ x: 100, y: 100 });
  const [widgetSize, setWidgetSize] = useState({ width: 550, height: 400 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });

  const widgetRef = useRef(null);
  const resizeStartRef = useRef({ x: 0, y: 0, width: 0, height: 0 });

  // Initialize position and load history
  useEffect(() => {
    const startX = (window.innerWidth / 2) - 275;
    const startY = window.innerHeight * 0.12;
    setWidgetPos({ x: startX, y: startY });

    const savedHistory = localStorage.getItem('astra_news_history');
    if (savedHistory) {
      try {
        setNewsHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error('Error loading news history:', e);
      }
    }
  }, []);

  // Apply dynamic text scaling based on widget size
  const applyDynamicScaling = () => {
    if (!widgetRef.current) return;

    const baseWidth = 550;
    const baseHeight = 400;
    const scaleX = widgetSize.width / baseWidth;
    const scaleY = widgetSize.height / baseHeight;
    const avgScale = (scaleX + scaleY) / 2;

    // Different scaling strategies for different content types
    const dampedScale = Math.pow(avgScale, 0.6);
    const textScale = Math.pow(avgScale, 0.7);
    const elementScale = Math.pow(avgScale, 0.8);

    // Clamp scales to reasonable bounds
    const clampedScale = Math.max(0.5, Math.min(2.5, dampedScale));
    const clampedTextScale = Math.max(0.6, Math.min(2.0, textScale));
    const clampedElementScale = Math.max(0.7, Math.min(2.2, elementScale));

    // Apply CSS variables for dynamic scaling
    widgetRef.current.style.setProperty('--text-scale', clampedTextScale);
    widgetRef.current.style.setProperty('--element-scale', clampedElementScale);
    widgetRef.current.style.setProperty('--base-scale', clampedScale);
  };

  // Apply scaling whenever size changes
  useEffect(() => {
    applyDynamicScaling();
  }, [widgetSize]);

  // Handle incoming news from AI
  useEffect(() => {
    if (initialNews) {
      const content = typeof initialNews === 'object' ? initialNews.content : initialNews;
      handleNewNews(content);
    }
  }, [initialNews]);

  // Update Italy time every second
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      // Create a date object with Italy's timezone
      const italyTime = new Date(now.toLocaleString("en-US", {timeZone: "Europe/Rome"}));
      const timeString = italyTime.toLocaleTimeString('it-IT', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: false
      });
      setItalyTime(timeString);
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const handleNewNews = async (content) => {
    if (!content) return;
    setIsLoading(true);
    setActiveTab('current');

    try {
      // Parse the news content
      let articles = [];

      // Check if the text contains structured news data
      if (content.includes('HEADLINE:') || content.includes('SOURCE:')) {
        articles = parseStructuredNews(content);
      } else {
        // Handle plain text news
        const headline = extractHeadlineFromText(content);
        const source = extractSourceFromText(content) || "News Feed";

        articles = [{
          headline: headline,
          summary: content, // FULL CONTENT - NO SUMMARIZATION
          source: source
        }];
      }

      setNewsArticles(articles);
      setNewsCount(articles.length);

      // Add to history
      const historyItem = {
        id: Date.now(),
        query: content.substring(0, 30) + (content.length > 30 ? '...' : ''),
        result: content,
        timestamp: new Date().toISOString(),
        date: new Date().toLocaleString()
      };

      const updatedHistory = [historyItem, ...newsHistory].slice(0, 50);
      setNewsHistory(updatedHistory);
      localStorage.setItem('astra_news_history', JSON.stringify(updatedHistory));
    } catch (error) {
      console.error('Error processing news:', error);
      // Fallback to simple text display
      setNewsArticles([{
        headline: "News Update",
        summary: content,
        source: "News Feed"
      }]);
    } finally {
      setIsLoading(false);

      if (widgetRef.current) {
        widgetRef.current.classList.add('new-result-glow');
        setTimeout(() => {
          if (widgetRef.current) widgetRef.current.classList.remove('new-result-glow');
        }, 3000);
      }
    }
  };

  const parseStructuredNews = (newsText) => {
    const articles = [];
    const sections = newsText.split(/(?=HEADLINE:|SOURCE:)/);

    let currentArticle = {};

    for (const section of sections) {
      if (section.includes('HEADLINE:')) {
        const lines = section.split('\n');
        for (const line of lines) {
          if (line.startsWith('HEADLINE:')) {
            currentArticle.headline = line.replace('HEADLINE:', '').trim();
          } else if (line.startsWith('SOURCE:')) {
            currentArticle.source = line.replace('SOURCE:', '').trim();
          } else if (line.startsWith('TIME:')) {
            currentArticle.time = line.replace('TIME:', '').trim();
          } else if (line.trim() && !line.startsWith('HEADLINE:') && !line.startsWith('SOURCE:') && !line.startsWith('TIME:')) {
            if (!currentArticle.summary) currentArticle.summary = '';
            currentArticle.summary += line.trim() + ' ';
          }
        }

        if (currentArticle.headline) {
          articles.push({
            headline: currentArticle.headline,
            summary: currentArticle.summary?.trim() || '',
            source: currentArticle.source || 'Unknown Source',
            time: currentArticle.time || 'Recently'
          });
          currentArticle = {};
        }
      }
    }

    return articles.length > 0 ? articles : [{
      headline: "News Update",
      summary: newsText,
      source: "News Feed",
      time: "Just now"
    }];
  };

  const extractHeadlineFromText = (text) => {
    // Extract a reasonable headline from the first sentence
    const firstSentence = text.split(/[.!?]/)[0].trim();

    // If first sentence is too long, truncate it
    if (firstSentence.length > 80) {
      const words = firstSentence.split(' ');
      if (words.length > 10) {
        return words.slice(0, 10).join(' ') + '...';
      }
      return firstSentence.substring(0, 80) + '...';
    }

    // If first sentence is too short, try to get more context
    if (firstSentence.length < 20) {
      const sentences = text.split(/[.!?]/).filter(s => s.trim().length > 0);
      if (sentences.length > 1) {
        const combined = sentences.slice(0, 2).join('. ').trim();
        return combined.length > 80 ? combined.substring(0, 80) + '...' : combined;
      }
    }

    return firstSentence || 'News Update';
  };

  const extractSourceFromText = (text) => {
    // Try to extract source from common patterns
    const sourcePatterns = [
      /(?:according to|reported by|from|source:|via)\s+([A-Za-z\s]+)/i,
      /\b([A-Z][a-z]+\s+News|[A-Z][a-z]+\s+Times|BBC|CNN|Reuters|AP|Reuters)\b/i
    ];

    for (const pattern of sourcePatterns) {
      const match = text.match(pattern);
      if (match) {
        return match[1].trim();
      }
    }

    return null; // Return null if no source found, will use default
  };

  // Drag handles
  useEffect(() => {
    if (!isDragging) return;
    const onMove = (e) => {
      setWidgetPos({
        x: e.clientX - dragOffset.x,
        y: e.clientY - dragOffset.y
      });
    };
    const onUp = () => setIsDragging(false);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, [isDragging, dragOffset]);

  // Resize handles
  useEffect(() => {
    if (!isResizing) return;
    const onMove = (e) => {
      setWidgetSize({
        width: Math.max(300, resizeStartRef.current.width + (e.clientX - resizeStartRef.current.x)),
        height: Math.max(200, resizeStartRef.current.height + (e.clientY - resizeStartRef.current.y))
      });
    };
    const onUp = () => setIsResizing(false);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, [isResizing]);

  const handleDragStart = (e) => {
    if (e.target.closest('.widget-controls') ||
      e.target.closest('.resize-handle') ||
      e.target.closest('.news-nav') ||  // Changed from news-nav-tab to news-nav to prevent dragging when clicking on any part of the nav
      e.target.closest('.copy-button') ||
      e.target.tagName === 'BUTTON' ||
      e.target.tagName === 'A') {
      return;
    }

    setIsDragging(true);
    setDragOffset({
      x: e.clientX - widgetPos.x,
      y: e.clientY - widgetPos.y
    });
  };

  const handleResizeStart = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
    resizeStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      width: widgetSize.width,
      height: widgetSize.height
    };
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text);
  };

  const viewHistoryItem = (item) => {
    handleNewNews(item.result);
    setActiveTab('current');
  };

  const increaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: prev.width + 100,
      height: prev.height + 100
    }));
  };

  const decreaseWidgetSize = () => {
    setWidgetSize(prev => ({
      width: Math.max(300, prev.width - 100),
      height: Math.max(200, prev.height - 100)
    }));
  };

  const formatNewsContent = (content) => {
    // Format the news content for display
    return content.split('\n\n').map((paragraph, index) =>
      paragraph.trim() ? `<p key="${index}">${paragraph.trim()}</p>` : ''
    ).join('');
  };

  return (
    <div
      ref={widgetRef}
      className={`news-widget ${isDragging ? 'widget-dragging' : ''} ${isResizing ? 'widget-resizing' : ''}`}
      style={{
        left: `${widgetPos.x}px`,
        top: `${widgetPos.y}px`,
        width: `${widgetSize.width}px`,
        height: `${widgetSize.height}px`,
      }}
      onMouseDown={handleDragStart}
    >
      <div className="corner-top-right"></div>
      <div className="corner-bottom-left"></div>

      <div className="resize-handle" onMouseDown={handleResizeStart}></div>

      <div className="widget-controls" onMouseDown={(e) => e.stopPropagation()}>
        <div className="widget-control-btn expand-btn" onClick={increaseWidgetSize} title="Make Bigger">⧨</div>
        <div className="widget-control-btn compress-btn" onClick={decreaseWidgetSize} title="Make Smaller">⧩</div>
        <div className="widget-control-btn close-btn" onClick={(e) => { e.stopPropagation(); onClose(); }} title="Close">⧬</div>
      </div>

      {/* Invisible hover area to ensure hover works properly */}
      <div className="hover-area"></div>

      <div className="news-wrapper">
        <div className="news-label">
          NEWS
        </div>

        {/* Navigation Tabs */}
        <div className="news-nav">
          <div
            className={`news-nav-tab ${activeTab === 'current' ? 'active' : ''}`}
            onClick={(e) => { e.stopPropagation(); setActiveTab('current'); }}
          >
            Current
          </div>
          <div
            className={`news-nav-tab ${activeTab === 'history' ? 'active' : ''}`}
            onClick={(e) => { e.stopPropagation(); setActiveTab('history'); }}
          >
            History
          </div>
        </div>

        {/* Content Area */}
        <div className="news-content-wrapper">
          {activeTab === 'current' ? (
            <>
              {isLoading ? (
                <div className="news-loading">
                  <div className="loading-spinner"></div>
                  Fetching latest headlines...
                </div>
              ) : (
                <div className={`news-current-view ${isLoading ? 'hidden' : ''}`}>
                  <div className="news-content">
                    {newsArticles.length > 0 ? (
                      newsArticles.map((article, index) => (
                        <div key={index} className="news-item" style={{ animationDelay: `${index * 0.1}s` }}>
                          <div className="news-meta">
                            <span className="news-category">{article.source}</span>
                            {article.time && <span className="news-time">{article.time}</span>}
                          </div>
                          <div className="news-headline">{article.headline}</div>
                          <div
                            className="news-summary"
                            dangerouslySetInnerHTML={{
                              __html: formatNewsContent(article.summary)
                            }}
                          />
                        </div>
                      ))
                    ) : (
                      <div className="news-item">
                        <div className="news-meta">
                          <span className="news-category">News Feed</span>
                        </div>
                        <div className="news-headline">No news available</div>
                        <div className="news-summary">Stay tuned for the latest updates.</div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Copy button for current news */}
              {!isLoading && newsArticles.length > 0 && (
                <div className="copy-button" onClick={(e) => { e.stopPropagation(); copyToClipboard(newsArticles.map(a => `${a.headline}\n\nSource: ${a.source}\n\n${a.summary}`).join('\n\n---\n\n')); }} title="Copy news articles">
                  <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M16 1H4C2.9 1 2 1.9 2 3V15H4V3H16V1ZM19 5H8C6.9 5 6 5.9 6 7V21C6 22.1 6.9 23 8 23H19C20.1 23 21 22.1 21 21V7C21 5.9 20.1 5 19 5ZM19 21H8V7H19V21Z" fill="currentColor" />
                  </svg>
                </div>
              )}
            </>
          ) : (
            <div className="news-history-view">
              {newsHistory.length === 0 ? (
                <div className="news-placeholder">No news history recorded in this session.</div>
              ) : (
                <div className="news-history-list">
                  {newsHistory.map(item => (
                    <div key={item.id} className="news-history-item" onClick={(e) => { e.stopPropagation(); viewHistoryItem(item); }}>
                      <div className="news-history-query">{item.query}</div>
                      <div className="news-history-date">{item.date}</div>
                      <div className="news-history-preview">{item.result.substring(0, 100)}...</div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default NewsWidget;
